## Code Example

```swift
// CoreData models: Ride, Driver, Route
// SwiftUI view: debounced search with 300ms
import SwiftUI
import Combine

class RideViewModel: ObservableObject {
  @Published var searchText: String = ""
  @Published private(set) var results: [Ride] = []
  private var cancellables = Set<AnyCancellable>()
  init(context: NSManagedObjectContext) {
    $searchText
      .debounce(for: .milliseconds(300), scheduler: DispatchQueue.main)
      .sink { text in
        self.fetchRides(matching: text, in: context)
      }
      .store(in: &cancellables)
  }

  private func fetchRides(matching text: String, in context: NSManagedObjectContext) {
    // NSFetchRequest with predicate on destination or route name
    let req: NSFetchRequest<Ride> = Ride.fetchRequest()
    if !text.isEmpty {
      req.predicate = NSPredicate(format: "destination CONTAINS[c] %@", text)
    }
    req.sortDescriptors = [NSSortDescriptor(key: "date", ascending: false)]
    do {
      results = try context.fetch(req)
    } catch {
      print(error)
    }
  }
}

struct RideListView: View {
  @StateObject var vm: RideViewModel
  var body: some View {
    VStack {
      TextField("Search rides…", text: $vm.searchText)
        .padding()
      List(vm.results, id: \.objectID) { ride in
        VStack(alignment: .leading) {
          Text(ride.destination ?? "Unknown")
          Text(ride.date ?? Date(), style: .date)
        }
      }
    }
  }
}
```

